#include <assert.h>

class Chain
{
public:
	bool IsInteresting() const;
	int GetScore() const;
};

class ScoringManager
{
	char pad[4772];
	Chain chain;
public:
	Chain & GetChain() { return chain; }
};

class kellyslater_controller
{
	ScoringManager my_scoreManager;
public:
	ScoringManager & get_my_scoreManager(void) { return my_scoreManager; }
};

class game
{
	char pad[180];
	int num_ai_players;
public:
	int get_num_ai_players() { return num_ai_players; }
};

class world_dynamics_system
{
	char pad[248];
	kellyslater_controller *ks_controller[2];
public:
	kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};

class stringx
{
	int data[3];
public:
	stringx(int);
	~stringx();
};

class TextString
{
	char pad[60];
public:
	bool checkTime;
	float time;
};

class TrickBoxText
{
	char pad[60];
public:
	bool checkTime;
	float time;
	bool no_color;
};

class RandomText : public TextString {};

class BurstTrickText
{
public:
	void Burst(TrickBoxText *);
};

class BurstText
{
public:
	void Burst(TextString *);
};

struct recti
{
	int x1, y1, x2, y2;
};

class IGOFrontEnd
{
	struct PLAYER
	{
		recti viewport;
		void *meterWidget;
		void *horizBalanceWidget;
		void *splitScoreWidget;
		void *splitMeterWidget;
		TrickBoxText *trickText;
		TextString *trickAttrText;
		RandomText *trickPointText;
		BurstTrickText *trickBurstText;
		BurstText *pointBurstText;
		TextString *tubeTimer;
		bool drawTubeTimer;
	};

	char pad[284];
	int numPlayers;
	int numActivePlayers;
	PLAYER *players;

	static int TRICK_WAIT_MAX;

public:
	void OnTrickChange(const int playerIdx, const bool bounce = true);
	void MakeTrickPointText(const int playerIdx, const stringx &text);
	void OnTrickComplete(const int playerIdx);
};

game *g_game_ptr;
world_dynamics_system *g_world_ptr;
int IGOFrontEnd::TRICK_WAIT_MAX = 3;

void IGOFrontEnd::OnTrickComplete(const int playerIdx)
{
    assert(playerIdx >= 0 && playerIdx < numPlayers);

	if (g_game_ptr->get_num_ai_players() && playerIdx)
		return;

	kellyslater_controller *	ksctrl = g_world_ptr->get_ks_controller(playerIdx);

	OnTrickChange(false);

	if (ksctrl->get_my_scoreManager().GetChain().IsInteresting())
	{
		players[playerIdx].trickText->no_color = true;
		players[playerIdx].trickText->checkTime = true;
		players[playerIdx].trickText->time = TRICK_WAIT_MAX;
		players[playerIdx].trickBurstText->Burst(players[playerIdx].trickText);

		MakeTrickPointText(playerIdx, stringx(ksctrl->get_my_scoreManager().GetChain().GetScore()));
		players[playerIdx].trickPointText->checkTime = true;
		players[playerIdx].trickPointText->time = TRICK_WAIT_MAX;
		players[playerIdx].pointBurstText->Burst(players[playerIdx].trickPointText);

		players[playerIdx].trickAttrText->time = TRICK_WAIT_MAX;
	}
}
